<div class="page-header"><div><span class="eyebrow">ACCOUNTABLE BY DESIGN</span><h1>A record you can rely on.</h1><p>Privileged actions, their actors and their timestamps. No silent changes.</p></div><span class="icon-tile blue"><?= icon('shield',25) ?></span></div><div class="toolbar"><form action="<?= e(route_url(route_path())) ?>" method="get" class="filter-form"><div class="search-field"><?= icon('search',17) ?><input name="q" type="search" maxlength="100" value="<?= e($_GET['q']??'') ?>" placeholder="Filter actions, e.g. content or user…" aria-label="Filter audit actions"></div><button class="btn btn-secondary">Filter actions</button></form><span class="results-label"><?= number($total) ?> records</span></div><section class="card table-card"><?php if($logs): ?><div class="table-responsive"><table class="data-table"><thead><tr><th>Action</th><th>Actor</th><th>Affected record</th><th>Details</th><th>Timestamp · UTC</th></tr></thead><tbody><?php foreach($logs as $log): ?><tr><td><span class="audit-action"><?= e($log['action']) ?></span></td><td><?= e($log['full_name']??'System / removed account') ?></td><td><?= e($log['entity_type']) ?> #<?= e($log['entity_id']) ?></td><td><div class="audit-details"><?= e($log['details']&&$log['details']!=='[]'?$log['details']:'—') ?></div></td><td style="white-space:nowrap"><?= niceDate($log['created_at'],'M j, Y · H:i:s') ?></td></tr><?php endforeach; ?></tbody></table></div><?php pagination($total,30); ?><?php else: emptyState('shield','No actions match this filter.','Try a broader action search. Audit records cannot be edited through this interface.','/admin/audit','See all actions');endif; ?></section><p class="fine-print" style="margin-top:18px">The application exposes no audit-edit or audit-delete endpoint. Database operators still require trusted operational controls and protected backups.</p>
